import { createDeliveryVerification } from './account-service/deliveryVerification.ts';
for (const chars of [4096, 131072, 524288, 2097152, 8388608]) {
 const result={requestChars:chars,warmVerifications:{}};
 for(const rows of [4,35,200]) {
  const cache=createDeliveryVerification(); let verifies=0;
  for(let pass=0;pass<2;pass++) {
   verifies=0;
   for(let i=0;i<rows;i++) await cache.check('account:'+i,JSON.stringify([{}, {}, 1,'x'.repeat(chars)])+':'+'0'.repeat(64),[new Uint8Array([1,2]),new Uint8Array([3,4])],async()=>{verifies++;return {verified:true};});
  }
  result.warmVerifications[rows]=verifies;cache.clear();
 }
 console.log(JSON.stringify(result));
}
